function verifyOperationCancelledAfter(content, cancelAfter, operation, validator, fileName, fileContent, options) {
  let checks = 0;
  const token = {
    isCancellationRequested() {
      checks++;
      const result = checks >= cancelAfter;
      if (result) {
        checks = -Infinity;
      }
      return result;
    }
  };
  const adapter = new Harness_LanguageService_exports.NativeLanguageServiceAdapter(token, options);
  const host = adapter.getHost();
  host.addScript(
    fileName || "file.ts",
    fileContent || content,
    /*isRootFile*/
    true
  );
  const service = adapter.getLanguageService();
  assertCancelled(() => operation(service));
  validator(operation(service));
}
function assertCancelled(cb) {
  let caught;
  try {
    cb();
  } catch (e) {
    caught = e;
  }
  assert.exists(caught, "Expected operation to be cancelled, but was not");
  assert.instanceOf(caught, OperationCanceledException);
}
