// src/testRunner/unittests/helpers/tsserver.ts
function baselineTsserverLogs(scenario2, subScenario, sessionOrService) {
  Baseline.runBaseline(`tsserver/${scenario2}/${subScenario.split(" ").join("-")}.js`, sessionOrService.logger.logs.join("\r\n"));
}
function toExternalFile(fileName) {
  return { fileName };
}
function toExternalFiles(fileNames) {
  return map(fileNames, toExternalFile);
}
