    describe("unittests:: tsserver:: typingsInstaller:: Validate package name:", () => {
      it("name cannot be too long", () => {
        let packageName = "a";
        for (let i = 0; i < 8; i++) {
          packageName += packageName;
        }
        assert.equal(validatePackageName2(packageName), NameValidationResult2.NameTooLong);
      });
      it("package name cannot start with dot", () => {
        assert.equal(validatePackageName2(".foo"), NameValidationResult2.NameStartsWithDot);
      });
      it("package name cannot start with underscore", () => {
        assert.equal(validatePackageName2("_foo"), NameValidationResult2.NameStartsWithUnderscore);
      });
      it("package non URI safe characters are not supported", () => {
        assert.equal(validatePackageName2("  scope  "), NameValidationResult2.NameContainsNonURISafeCharacters);
        assert.equal(validatePackageName2("; say \u2018Hello from TypeScript!\u2019 #"), NameValidationResult2.NameContainsNonURISafeCharacters);
        assert.equal(validatePackageName2("a/b/c"), NameValidationResult2.NameContainsNonURISafeCharacters);
      });
      it("scoped package name is supported", () => {
        assert.equal(validatePackageName2("@scope/bar"), NameValidationResult2.Ok);
      });
      it("scoped name in scoped package name cannot start with dot", () => {
        assert.deepEqual(validatePackageName2("@.scope/bar"), { name: ".scope", isScopeName: true, result: NameValidationResult2.NameStartsWithDot });
        assert.deepEqual(validatePackageName2("@.scope/.bar"), { name: ".scope", isScopeName: true, result: NameValidationResult2.NameStartsWithDot });
      });
      it("scope name in scoped package name cannot start with underscore", () => {
        assert.deepEqual(validatePackageName2("@_scope/bar"), { name: "_scope", isScopeName: true, result: NameValidationResult2.NameStartsWithUnderscore });
        assert.deepEqual(validatePackageName2("@_scope/_bar"), { name: "_scope", isScopeName: true, result: NameValidationResult2.NameStartsWithUnderscore });
      });
      it("scope name in scoped package name with non URI safe characters are not supported", () => {
        assert.deepEqual(validatePackageName2("@  scope  /bar"), { name: "  scope  ", isScopeName: true, result: NameValidationResult2.NameContainsNonURISafeCharacters });
        assert.deepEqual(validatePackageName2("@; say \u2018Hello from TypeScript!\u2019 #/bar"), { name: "; say \u2018Hello from TypeScript!\u2019 #", isScopeName: true, result: NameValidationResult2.NameContainsNonURISafeCharacters });
        assert.deepEqual(validatePackageName2("@  scope  /  bar  "), { name: "  scope  ", isScopeName: true, result: NameValidationResult2.NameContainsNonURISafeCharacters });
      });
      it("package name in scoped package name cannot start with dot", () => {
        assert.deepEqual(validatePackageName2("@scope/.bar"), { name: ".bar", isScopeName: false, result: NameValidationResult2.NameStartsWithDot });
      });
      it("package name in scoped package name cannot start with underscore", () => {
        assert.deepEqual(validatePackageName2("@scope/_bar"), { name: "_bar", isScopeName: false, result: NameValidationResult2.NameStartsWithUnderscore });
      });
      it("package name in scoped package name with non URI safe characters are not supported", () => {
        assert.deepEqual(validatePackageName2("@scope/  bar  "), { name: "  bar  ", isScopeName: false, result: NameValidationResult2.NameContainsNonURISafeCharacters });
        assert.deepEqual(validatePackageName2("@scope/; say \u2018Hello from TypeScript!\u2019 #"), { name: "; say \u2018Hello from TypeScript!\u2019 #", isScopeName: false, result: NameValidationResult2.NameContainsNonURISafeCharacters });
      });
    });
